$node
.select('rect')
.attr('y', d => ((d.x1 - d.x0) * height - d.h) / 2)
.attr('height', d => d.h);
// node = d
const stackData = [];
$node.each(node => {
if (!node.children) return false;
const st = stack(node);
st.forEach((s, i) => {
stackData.push({
...s,
node,
child: node.children[i]
