const midPosChild = (bR - tR) / 2;
const delta = (tR - tL) / 2;
const y = tL + midPosChild + delta;
return y;
})
.attr('x', linkWidth / 2)
.style('font-size', d => `${scaleFont(d.child.value)}px`)
